	expect(parseArgs([]).loadTimeoutMs).toBe(15_000);
	expect(parseArgs(["--load-timeout", "0"]).loadTimeoutMs).toBe(0);
	expect(parseArgs(["--load-timeout", "2.5"]).loadTimeoutMs).toBe(2500);
	expect(captureExit(() => parseArgs(["--load-timeout", "x"])).code).not.toBe(0);
});

test("a clean open never attaches to a browser already on the port", async () => {
	const { ownsBrowserOn } = await import("./open.ts");
	expect(await ownsBrowserOn(9222, { clean: true, userDataDir: undefined })).toBe(false);
});

test("a profile whose SingletonLock names a live pid is reported as held", async () => {
	const { profileHolderPid } = await import("./open.ts");
	const { mkdtempSync, symlinkSync, rmSync } = await import("node:fs");
	const { join } = await import("node:path");
	const { tmpdir } = await import("node:os");
	const live = mkdtempSync(join(tmpdir(), "holder-"));
	symlinkSync(`host-${process.pid}`, join(live, "SingletonLock"));
	expect(profileHolderPid(live)).toBe(process.pid);
	const dead = mkdtempSync(join(tmpdir(), "holder-"));
	symlinkSync("host-999999999", join(dead, "SingletonLock"));
	expect(profileHolderPid(dead)).toBeNull();
	expect(profileHolderPid(join(tmpdir(), "no-such-profile"))).toBeNull();
	rmSync(live, { recursive: true });
	rmSync(dead, { recursive: true });
});

test("script runs only keep the extension they load", async () => {
	const { extensionArgs } = await import("./open.ts");
	expect(
		extensionArgs({ loadExtension: undefined, keepExtensions: false, headless: true }),
	).toEqual(["--disable-extensions"]);
	expect(
		extensionArgs({ loadExtension: "/x", keepExtensions: false, headless: false }),
	).toEqual(["--load-extension=/x", "--disable-extensions-except=/x"]);
});

test("a windowed run that loads nothing keeps the profile's extensions", async () => {
	const { extensionArgs } = await import("./open.ts");
	expect(
		extensionArgs({ loadExtension: undefined, keepExtensions: false, headless: false }),
	).toEqual([]);
});

test("--keep-extensions leaves the profile's extensions alone", async () => {
	const { extensionArgs } = await import("./open.ts");
	expect(
		extensionArgs({ loadExtension: undefined, keepExtensions: true, headless: false }),
	).toEqual([]);
	expect(
		extensionArgs({ loadExtension: "/x", keepExtensions: true, headless: false }),
	).toEqual(["--load-extension=/x"]);
});

test("--dev-selector adds Dev Selector without isolating a windowed profile", async () => {
	const { extensionArgs } = await import("./open.ts");
	expect(
		extensionArgs({ loadExtension: undefined, keepExtensions: false, headless: false, selectorDir: "/s" }),
	).toEqual(["--load-extension=/s"]);
	expect(
		extensionArgs({ loadExtension: "/x", keepExtensions: false, headless: false, selectorDir: "/s" }),
	).toEqual(["--load-extension=/x,/s", "--disable-extensions-except=/x,/s"]);
	expect(
		extensionArgs({ loadExtension: undefined, keepExtensions: false, headless: true, selectorDir: "/s" }),
	).toEqual(["--load-extension=/s", "--disable-extensions-except=/s"]);
});

test("resolveDevSelectorDir picks the newer build and names a missing one", async () => {
	const { resolveDevSelectorDir } = await import("./open.ts");
	const { mkdtempSync, mkdirSync, writeFileSync, utimesSync, rmSync } = await import("node:fs");
	const { join } = await import("node:path");
	const { tmpdir } = await import("node:os");
	const root = mkdtempSync(join(tmpdir(), "ds-"));
	for (const [name, age] of [["chrome-mv3", 10], ["chrome-mv3-dev", 1000]] as const) {
		const dir = join(root, ".output", name);
		mkdirSync(dir, { recursive: true });
		writeFileSync(join(dir, "manifest.json"), "{}");
		const t = new Date(Date.now() - age * 1000);
		utimesSync(join(dir, "manifest.json"), t, t);
