export function resolveDevSelectorDir(root: string): string {
  const candidates = [join(root, ".output", "chrome-mv3"), join(root, ".output", "chrome-mv3-dev")];
  const builds = candidates.map(dir => { try { return {dir, mtime: statSync(join(dir,"manifest.json")).mtimeMs} } catch { return null } }).filter(...)
  if (!builds.length) die(`Dev Selector build not found: expected ${candidates.join(" or ")} (run the extension build first)`);
  builds.sort((a,b)=> b.mtime - a.mtime);
  return builds[0].dir;
}

