export function extensionArgs(options: Pick<OpenOptions,"loadExtension"|"keepExtensions"|"headless"|"selectorDir">): string[] {
	const dirs = mergeExtensionDirs(options.loadExtension, options.selectorDir);
	if (!dirs) {
		return options.keepExtensions || !options.headless ? [] : ["--disable-extensions"];
