/** Keep every matching window minimized at map time; do not unload on first match. */
async function installKWinStartupMinimize(
	className: string,
): Promise<KWinStartupMinimizeHandle | null> {
	if (!canUseKWin()) return null;

	const pluginName = `browser-start-minimize-${className}-${Date.now()}`;
	const cls = kwinClassLiteral(className);
	const scriptSource = `function maybeHandle(window) {
	if (!window || !window.normalWindow) return;
	if (String(window.resourceClass) !== ${cls}) return;
	window.minimized = true;
}
workspace.windowAdded.connect(maybeHandle);
for (const window of workspace.stackingOrder) maybeHandle(window);
`;

	try {
		const loaded = await loadKWinScript(scriptSource, pluginName);
		return {
			dispose: () =>
				unloadKWinScript(pluginName, loaded.scriptDir),
		};
	} catch (error) {
		console.warn(
			`[open] KWin startup minimize hook unavailable: ${error instanceof Error ? error.message : String(error)}`,
		);
		return null;
	}
}

async function kwinMinimizeByClass(className: string): Promise<boolean> {
	if (!canUseKWin()) return false;
	const pluginName = `browser-force-minimize-${className}-${Date.now()}`;
	const cls = kwinClassLiteral(className);
	const scriptSource = `for (const w of workspace.stackingOrder) {
	if (!w.normalWindow) continue;
	if (String(w.resourceClass) !== ${cls}) continue;
	w.minimized = true;
}
callDBus("org.kde.KWin", "/Scripting", "org.kde.kwin.Scripting", "unloadScript", ${JSON.stringify(pluginName)});
`;
	try {
		const loaded = await loadKWinScript(scriptSource, pluginName);
		const finished = await waitUntilKWinScriptUnloaded(pluginName, 2000);
		if (!finished) {
			await unloadKWinScript(pluginName, loaded.scriptDir);
		} else {
			await rm(loaded.scriptDir, { recursive: true, force: true }).catch(
				() => undefined,
			);
		}
		return true;
	} catch (error) {
		console.warn(
			`[open] KWin minimize unavailable: ${error instanceof Error ? error.message : String(error)}`,
		);
		return false;
	}
}

async function kwinClassIsMinimized(className: string): Promise<boolean | null> {
	if (!canUseKWin()) return null;
	const tag = `KWINMIN$${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}`;
	const pluginName = `browser-min-read-${className}-${Date.now()}`;
	const cls = kwinClassLiteral(className);
	const scriptSource = `const cls = ${cls};
for (const w of workspace.stackingOrder) {
	if (!w.normalWindow) continue;
	if (String(w.resourceClass) !== cls) continue;
	print(${JSON.stringify(tag)} + " min=" + w.minimized + " active=" + w.active);
}
callDBus("org.kde.KWin", "/Scripting", "org.kde.kwin.Scripting", "unloadScript", ${JSON.stringify(pluginName)});
`;
	try {
		const loaded = await loadKWinScript(scriptSource, pluginName);
		const finished = await waitUntilKWinScriptUnloaded(pluginName, 2000);
		if (!finished) {
			await unloadKWinScript(pluginName, loaded.scriptDir);
		} else {
			await rm(loaded.scriptDir, { recursive: true, force: true }).catch(
				() => undefined,
			);
		}
		await Bun.sleep(300);
		const log = Bun.spawnSync({
			cmd: [
				"journalctl",
				"--user",
				"--since",
				"15 seconds ago",
				"--no-pager",
			],
			stdout: "pipe",
			stderr: "pipe",
		});
		const text = new TextDecoder().decode(log.stdout);
		const lines = text.split("\n").filter((line) => line.includes(tag));
		if (!lines.length) return null;
		return lines.every(
			(line) => line.includes("min=true") && !line.includes("active=true"),
		);
	} catch {
		return null;
	}
}

/**
 * A browser already answering on the port is attached to (and its tabs reset)
 * only when it is ours: a global-profile port, shared on purpose (9222, 9201),
 * or one launched from the profile this call would use. Another project's or
 * run's browser on that port is left alone and a free port is used instead.
 */
export async function ownsBrowserOn(
	port: number,
	options: Pick<OpenOptions, "clean" | "userDataDir">,
): Promise<boolean> {
	if (options.clean) return false;
	const dir = options.userDataDir ?? resolveDefaultProfileDir(port);
	if (dir === globalProfileDir(port)) return true;
	const info = await readLaunchInfo(dir).catch(() => null);
	if (!info?.pid || info.port !== port || !processExists(info.pid)) return false;
	return (await processMatchesLaunchInfo({ pid: info.pid, port, userDataDir: dir })) !== false;
}

/**
 * A run that loads an extension starts with only that one: a force-installed
 * blocker (a managed policy) holds a site's subresources until its own filter
 * lists settle, which left the tab on about:blank or "loading" forever.
 *
 * A run that loads none keeps the profile's extensions, because they are the
 * reason it pointed at that profile — a signed-in Tampermonkey on port 12345
 * is the tool being driven, not noise. Headless runs stay bare by default
 * (`--disable-extensions`), as before. `--keep-extensions` opts a
 * `--load-extension` run back into the profile's extensions too.
 */
export function extensionArgs(
	options: Pick<OpenOptions, "loadExtension" | "keepExtensions" | "headless">,
): string[] {
	const args: string[] = [];
	if (options.loadExtension) args.push(`--load-extension=${options.loadExtension}`);
	if (options.keepExtensions) return args;
	if (options.loadExtension) args.push(`--disable-extensions-except=${options.loadExtension}`);
	else if (options.headless) args.push("--disable-extensions");
	return args;
}

