export function extensionArgs(
	options: Pick<
		OpenOptions,
		"loadExtension" | "selectorDir" | "keepExtensions" | "headless"
	>,
): string[] {
	const dirs = mergeExtensionDirs(options.loadExtension, options.selectorDir);
	if (!dirs) {
		return options.keepExtensions || !options.headless
			? []
			: ["--disable-extensions"];
	}
	const args = [`--load-extension=${dirs}`];
	if (options.keepExtensions) return args;
	// A windowed run that loads only the Dev Selector keeps the profile's own
	// extensions: it was pointed at that profile on purpose.
	if (options.loadExtension || options.headless)
		args.push(`--disable-extensions-except=${dirs}`);
	return args;
}

/** The newest build of the Dev Selector extension under `<root>/.output`. */
export function resolveDevSelectorDir(root: string): string {
	const candidates = ["chrome-mv3", "chrome-mv3-dev"].map((name) =>
		join(root, ".output", name),
	);
	const builds = candidates
		.map((dir) => {
			try {
				return { dir, mtime: statSync(join(dir, "manifest.json")).mtimeMs };
			} catch {
				return null;
			}
		})
		.filter((build): build is { dir: string; mtime: number } => build !== null)
		.sort((a, b) => b.mtime - a.mtime);
	if (!builds.length)
		die(
			`Dev Selector build not found: expected ${candidates.join(" or ")} (build the extension first)`,
		);
	return builds[0].dir;
}

